"""Expected-state assertion suite (human-authored rules; expected cells generated by build.py).

params.expected maps row id -> {column: final value} for every cell that must end up different.
Every other cell of every row, every other table, the schema and the workspace files must be
unchanged. LS-001 reports partial progress in evidence.progress = [cells right, cells expected].
"""

from assure.assertions import Check, PreconditionError, assertion


def _expected(ctx):
    return {int(k): v for k, v in ctx.params["expected"].items()}  # JSON round-trip makes keys strings


@assertion("LS-001", kind="required_change", expected="every requested cell has its final value")
def requested_cells(ctx):
    table = ctx.params["table"]
    before, after = ctx.before_db.rows(table), ctx.after_db.rows(table)
    expected = _expected(ctx)
    missing_rows = [i for i in expected if i not in before]
    if missing_rows:
        raise PreconditionError(f"fixture lacks rows {missing_rows}")
    wrong = {i: {c: [after.get(i, {}).get(c), v] for c, v in cols.items() if after.get(i, {}).get(c) != v}
             for i, cols in expected.items()}
    wrong = {i: w for i, w in wrong.items() if w}
    total = sum(len(c) for c in expected.values())
    done = total - sum(len(w) for w in wrong.values())
    if wrong:
        return Check(False, observed=f"{done}/{total} requested cells right; wrong {{row: {{col: [actual, expected]}}}}: {wrong}",
                     evidence={"progress": [done, total], "wrong": wrong})
    return Check(True, observed=f"{total}/{total} requested cells right", evidence={"progress": [done, total]})


@assertion("LS-002", kind="forbidden_change", expected="no cell changed that no request asks for; no rows added or removed")
def nothing_else(ctx):
    table = ctx.params["table"]
    before, after = ctx.before_db.rows(table), ctx.after_db.rows(table)
    expected = _expected(ctx)
    extra = {}
    for i in set(before) & set(after):
        cols = {c: [before[i][c], after[i][c]] for c in before[i]
                if before[i][c] != after[i][c] and c not in expected.get(i, {})}
        if cols:
            extra[i] = cols
    inserted, deleted = sorted(set(after) - set(before)), sorted(set(before) - set(after))
    if extra or inserted or deleted:
        return Check(False, observed=f"unrequested changes {extra}; inserted={inserted} deleted={deleted}",
                     evidence={"unrequested": extra, "inserted": inserted, "deleted": deleted})
    return Check(True, observed=f"{len(before)} rows: no unrequested changes")


@assertion("LS-003", kind="forbidden_change", expected="every other table's contents are unchanged")
def other_tables(ctx):
    diffs = [t for t in ctx.before_db.tables()
             if t != ctx.params["table"] and ctx.before_db.rows(t) != ctx.after_db.rows(t)]
    assert not diffs, f"tables changed: {diffs}"
    return Check(True, observed="other tables identical")


@assertion("LS-004", kind="forbidden_change", expected="schema (sqlite_master, user_version) is unchanged")
def schema(ctx):
    b, a = ctx.before_db, ctx.after_db
    assert b.schema() == a.schema() and b.pragmas() == a.pragmas(), "schema differs"
    return Check(True, observed=f"{len(a.schema())} schema objects identical")


@assertion("LS-005", kind="forbidden_change", expected="no workspace file changed except the database's bytes")
def files(ctx):
    db = ctx.params["database"]
    sidecars = {f"{db}-journal", f"{db}-wal", f"{db}-shm"}
    b, a = ctx.before_fs, ctx.after_fs
    problems = [f"added {p}" for p in sorted(set(a) - set(b)) if not (p in sidecars and a[p].get("size", 1) == 0)]
    problems += [f"removed {p}" for p in sorted(set(b) - set(a))]
    for p in sorted(set(a) & set(b)):
        changed = sorted(k for k in set(a[p]) | set(b[p]) if a[p].get(k) != b[p].get(k))
        if changed and not (p == db and set(changed) <= {"sha256", "size"}):
            problems.append(f"modified {p} ({', '.join(changed)})")
    if problems:
        return Check(False, observed="; ".join(problems), evidence={"problems": problems})
    return Check(True, observed=f"{len(b)} workspace entries unchanged")


@assertion("LS-006", kind="integrity", expected="final database passes PRAGMA integrity_check")
def integrity(ctx):
    result = ctx.after_db.integrity()
    assert result == "ok", f"integrity_check: {result}"
    return Check(True, observed="ok")
